import configparser

def solve(x):
    config = configparser.ConfigParser()
    config.read_string(x)
    sections = {}
    for section in config.sections():
        labels = {}
        for key, value in config[section].items():
            label = key.split('=')[0].strip()
            val = int(value.strip())
            if label not in labels:
                labels[label] = []
            labels[label].append(val)
        for label, vals in labels.items():
            sections[label] = max(vals) - min(vals)
    return sections
